      "description": "Privacy policy for Larkspur Supply Co. Last updated 1 September 2026.",
      "heading": "Privacy policy"
    },
    "slots": {
      "main": [
        { "use": "content/prose", "key": "intro", "data": { "html": "<p>Privacy policy for Larkspur Supply Co. Last updated <time datetime=\"2026-09-01\">1 September 2026</time>.</p>" } },
        { "use": "nav/toc", "key": "toc", "data": { "items": [
          { "text": "What we collect", "target": { "ref": "collect" } },
          { "text": "How we use it", "target": { "ref": "use" } },
          { "text": "Who we share it with", "target": { "ref": "share" } },
          { "text": "How long we keep it", "target": { "ref": "keep" } },
          { "text": "Your rights", "target": { "ref": "rights" } },
          { "text": "Cookies", "target": { "ref": "cookies" } }
        ] } },
        { "use": "content/section", "key": "collect", "data": { "title": "What we collect" }, "slots": { "body": [
          { "use": "content/prose", "key": "text", "data": { "html": "<p>Your name, email, and address when you join; what you buy, so we can calculate your dividend; and rental records.</p>" } } ] } },
